// lib/segment/src/types.rs:833-856 (qdrant v1.18.0)
#[derive(Debug, Deserialize, Serialize, JsonSchema, Clone, Copy, PartialEq, Eq, Hash, Default)]
#[serde(rename_all = "snake_case")]
pub enum BinaryQuantizationEncoding {
    #[default]
    OneBit,
    TwoBits,
    OneAndHalfBits,
}

#[derive(Clone, Debug, Eq, PartialEq, Hash, Deserialize, Serialize, JsonSchema, Validate)]
#[serde(rename_all = "snake_case")]
pub struct BinaryQuantizationConfig {
    #[serde(skip_serializing_if = "Option::is_none")]
    pub always_ram: Option<bool>,
    #[serde(default)]
    #[serde(skip_serializing_if = "Option::is_none")]
    pub encoding: Option<BinaryQuantizationEncoding>,
    // ...
}

// lib/segment/src/vector_storage/quantized/quantized_vectors.rs:2269-2281
fn convert_binary_encoding(
    encoding: Option<BinaryQuantizationEncoding>,
) -> quantization::encoded_vectors_binary::Encoding {
    match encoding {
        Some(BinaryQuantizationEncoding::OneBit) => Encoding::OneBit,
        Some(BinaryQuantizationEncoding::TwoBits) => Encoding::TwoBit,
        Some(BinaryQuantizationEncoding::OneAndHalfBits) => Encoding::OneAndHalfBits,
        None => quantization::encoded_vectors_binary::Encoding::OneBit,
    }
}
